use std::{collections::HashMap, io::BufRead};

use clap::Parser;

fn main() {
    match Args::parse() {
        Args::Script(x) => x.run(),
    }
}

#[derive(Parser)]
enum Args {
    Script(Script),
}

#[derive(Debug)]
enum Range {
    Single(u32),
    Range(u32, u32),
}

#[derive(Parser)]
struct Script {}
impl Script {
    pub fn run(self) {
        let mut range_by_script = HashMap::new();
        for x in std::io::stdin().lock().lines() {
            let x = x.expect("failed to read");
            if x.trim().is_empty() || x.starts_with("#") {
                continue;
            }

            let mut parts = x.splitn(2, ';');
            let range = parts.next().expect("empty line?").trim();
            let mut scripts = parts.next().expect("empty line?").trim().splitn(2, '#');
            let script = scripts.next().expect("empty").trim();

            let mut range = range.splitn(2, "..");
            let range1 =
                u32::from_str_radix(range.next().expect("empty").trim(), 16).expect("invalid hex");
            let range = match range.next() {
                Some(r) => Range::Range(range1, u32::from_str_radix(r, 16).expect("invalid hex")),
                None => Range::Single(range1),
            };

            range_by_script
                .entry(script.to_owned())
                .or_insert_with(Vec::new)
                .push(range);
        }

        println!(
            "//! autogenerated from unicode public data files: https://www.unicode.org/Public/14.0.0/ucd/Scripts.txt"
        );
        println!("//!");
        for x in include_str!("../../LICENSE-UNICODE").lines() {
            println!("//! {x}");
        }
        println!("#![allow(unused_parens)]");
        println!();

        let mut range_by_script = range_by_script.into_iter().collect::<Vec<_>>();
        range_by_script.sort_by(|a, b| a.0.cmp(&b.0));
        for (k, v) in range_by_script {
            if k == "Common" {
                // commonは用途がないので生成しない
                continue;
            }

            println!(
                "pub const fn is_{k}(c: char) -> bool {{",
                k = pascal_to_snake(&k)
            );
            println!("    let c = c as u32;");
            println!(
                "    {}",
                v.iter()
                    .map(|x| match x {
                        Range::Single(v) => format!("c == {v:#04x}"),
                        Range::Range(start, end) =>
                            format!("({start:#04x} <= c && c <= {end:#04x})"),
                    })
                    .collect::<Vec<_>>()
                    .join(" || ")
            );
            println!("}}");
        }
    }
}

fn pascal_to_snake(s: &str) -> String {
    // PascalCase to snake_case
    let mut result = String::new();
    let mut last_underscore = false;
    for c in s.chars() {
        if c.is_uppercase() {
            if !result.is_empty() && !last_underscore {
                result.push('_');
                last_underscore = true;
            }
            result.push_str(&c.to_lowercase().to_string());
        } else {
            result.push(c);
            last_underscore = c == '_';
        }
    }

    result
}
